  // 例：document.createElement('div') -> documentRef.createElement('div')
  // 既存のローカル変数へのアクセスも documentRef を通じて行う
  // ... (中略) ...
}
```

### ステップ 3: Live-View 側の統合 (`src/live-view-entry.js`)
Worker を起動し、HTML 文字列を取得して DOM に流し込みます。

```javascript
// src/live-view-entry.js
const worker = new Worker('src/lib/support-rank-renderer.worker.js');

//

## 結論
最小・最確実な設計は案1: paintTopSupportRankStyleIntoElement を src/lib の共有モジュールに【そのまま抽出】し、依存(B)を引数(opts)で注入できる形にして、popup と live-view の両方から import する。

## 根拠
案1は、paintTopSupportRankStyleIntoElement の本体を共有モジュール化することで、完全コピーを保証し、popup の挙動を変更せずに live-view で同じ描画結果を得ることができる。また、依存(B)を引数で注入できる形にすることで、live-view の実装を最小限に抑え、将来のサーバー公開版への移植性も確保できる。

## 反論・リスク
しかし、案1では、paintTopSupportRankStyleIntoElement の依存(B)をすべて引数で注入できる必要があり、実装コストが増加する可能性がある。また、依存(B)の中には、popup の module-level state などの複雑な依存関係があるため、完全に引数で注入できるわけではない可能性もある。

## 具体案
具体的な実装案としては、次のようになる。
```javascript
// src/lib/paintTopSupportRankStyleIntoElement.js
export function paintTopSupportRankStyleIntoElement(opts) {
  // 依存(B)を引数で注入
  const {
    getStoryColorScheme,
    storyAvatarLoadGuard,
    anonymousIdenticonRuntimeEnabled,
    getCachedAnonymousIdenticonDataUrl,
    bindOnErrorHandlersWithin,
    upgradeAnonymousAvatarImageFromFallback,
    teardownNorthStarLaneWaitingUi,
    setNorthStarLaneHidden,
    syncNorthStarLaneGadgetFromBodyState,
    clearNorthStarVerticalRailForBody,
    paintNorthStarGiftHistorySummaryGadget,
    _topSupportRankLastHtmlByEl,
  } = opts;

  // paintTopSupportRankStyleIntoElement の本体
  // ...
}

// popup-entry.js
import { paintTopSupportRankStyleIntoElement } from '../lib/paintTopSupportRankStyleIntoElement';

// 依存(B)を注入
const opts = {
  getStoryColorScheme,
  storyAvatarLoadGuard,
  anonymousIdenticonRuntimeEnabled,
  getCachedAnonymousIdenticonDataUrl,
  bindOnErrorHandlersWithin,
  upgradeAnonymousAvatarImageFromFallback,
  teardownNorthStarLaneWaitingUi,
  setNorthStarLaneHidden,
  syncNorthStarLaneGadgetFromBodyState,
  clearNorthStarVerticalRailForBody,
  paintNorthStarGiftHistorySummaryGadget,
  _topSupportRankLastHtmlByEl,
};

paintTopSupportRankStyleIntoElement(opts);

// live-view-entry.js
import { paintTopSupportRankStyleIntoElement } from '../lib/paintTopSupportRankStyleIntoElement';

// 依存(B)を最小スタブで注入
const opts = {
  getStoryColorScheme: () => 'light',
  storyAvatarLoadGuard: () => {},
  anonymousIdenticonRuntimeEnabled: false,
  getCachedAnonymousIdenticonDataUrl: () => '',
  bindOnErrorHandlersWithin: () => {},
  upgradeAnonymousAvatarImageFromFallback: () => {},
  teardownNorthStarLaneWaitingUi: () => {},
  setNorthStarLaneHidden: () => {},
  syncNorthStarLaneGadgetFromBodyState: () => {},
  clearNorthStarVerticalRailForBody: () => {},
  paintNorthStarGiftHistorySummaryGadget: () => {},
  _topSupportRankLastHtmlByEl: () => {},
};

paintTopSupportRankStyleIntoElement(opts);
```
この実装では、paintTopSupportRankStyleIntoElement を共有モジュール化し、依存(B)を引数で注入できる形にしています。popup と live-view の両方で同じ描画結果を得ることができ、将来のサーバー公開版への移植性も確保されています。
